const chapters=[
 ['切尔诺伯格正在崩塌。罗德岛接应队护送博士穿过街区。','整合运动的追兵逼近，Ace守住撤离通道。','W的伏击封住去路，队伍必须拆开路障。','塔露拉现身。Ace为队伍争取时间，撤离的道路就在路障之后。'],
 ['龙门外围的感染者营地卷入战火，近卫局与罗德岛共同清理街区。','流民在火力封锁中寻找出口，护送队伍穿过关卡。','爆炸物封锁通路，敌方狙击手占据高处。','近卫局需要时间重整防线，罗德岛承担掩护任务。'],
 ['雪怪小队进入战场，低温正在改变战局。','暴风雪遮断视线，队伍必须坚持到接应到来。','冰障截断出口，凿开通道才能继续前进。','霜星挡在撤离方向。活着带走同伴，就是此刻的任务。'],
 ['废弃建筑里传来宿主的脚步声，梅菲斯特与浮士德仍在协同作战。','梅菲斯特驱使宿主推进，浮士德的箭矢藏在阴影中。','敌人的狂暴突袭打乱队形，必须稳住阵线。','爱国者行进在城中。罗德岛需要守住撤离窗口。'],
 ['龙门地下通道成为新的战线，敌我都在抢夺出口。','旁路门被封闭，只有打开通道才能疏散队伍。','追兵不断逼近，守住队伍的撤退秩序。','雷管埋在街区节点，爆破机会可以撼动敌方防线。'],
 ['切城核心区已成火海，罗德岛沿着最后的道路推进。','封闭的通风闸阻碍前进，及时开启可以恢复通道。','阿米娅与陈准备迎战塔露拉，冷却装置维系着战场。','双剑在火焰中交锋。保护装置并维持协同，为她们争取决胜时机。'],
 ['维多利亚的街巷被战争吞没，队伍接应受困的平民。','战火在房屋间蔓延，救援不能等待。','石柱阻碍队伍，破坏它们可以改变战场。','敌方推进到据点，利用地形找到突破的机会。'],
 ['伦蒂尼姆的城防系统笼罩街区，潜入队伍必须寻找空隙。','驻军封锁出口，队伍需要在封锁完成前突破。','副炮正在校准，诱导锁定可以创造反击机会。','城防炮将再次落下，队伍必须守住最后的窗口。'],
 ['战争的余波仍在蔓延，罗德岛向深处推进。','敌军在复杂街巷布下伏击，掩护队友通过。','关键位置需要有人坚守，撤离队伍才能继续前进。','散热阀保护敌方装置，摧毁它们将打开战线。'],
 ['伪装与记忆的迷雾侵入队伍，必须辨明敌人的身份。','萨卡兹部队堵住前路，协同突围是唯一出口。','队伍的据点正在受压，守住掩体与撤离秩序。','身份锚点维系着异常战场，破坏它们才能脱离迷局。'],
 ['城市的战线逼近终点，罗德岛迎接最后的阻击。','残余防线需要有人坚守，支援火力才能抵达。','主炮仍有可用弹药。把握充能窗口，协同城防力量。','炮口锁定强敌，守住校准过程等待轰击。'],
 ['终局的异常笼罩大地，队伍寻找足以撼动战场的机会。','导航点决定队伍能否穿过危险区域。','受困者仍在等待，喘息与休整也能维持救援秩序。','茧笼闭合在战场中心。同伴必须维持攻势，博士守住最后的协同窗口。']
];
export function narrative(spec){if(spec.solo){const notes={'N01-4':'塔露拉的火光封住街区。没有接应队，博士必须独自拆开路障，抢在烈焰合拢之前撤离。','N06-4':'双剑的决战成为远处的回声。博士独守装置阵线，以防御和休整维持冷却协同，或直接压制塔露拉。','N12-4':'茧笼闭合在心象中心。博士独自维持解缚窗口，让受困的回应穿过缝隙。'};if(notes[spec.id])return notes[spec.id];}if(spec.id==='VECTOR')return 'PRTS正在重建岛上干员的战术投影。试探对手的招式，寻找属于自己的突破。';if(spec.id==='SIM')return '战术模拟已启动。自由尝试技艺与编队，检验你的决策。';const m=/N(\d+)-(\d+)/.exec(spec.id);return m?chapters[Number(m[1])-1]?.[Number(m[2])-1]||'罗德岛已进入作战区域。': '罗德岛已进入作战区域。';}
const missions={
 'N01-3':'击退W；或破坏2处路障；或使W生命降至50%并坚持至第5轮。',
 'N01-4':'3轮内破坏2处路障（各500生命、60防御、30魔抗），博士存活即可撤离。',
 'N06-4':'击败塔露拉；或坚持至第8轮并累计6点协同。博士休整或防御、两名队友攻击的轮次，协同+1。',
 'N08-2':'6轮内击败敌方。',
 'N08-3':'完成2次炮击并存活。每次攻击充能+1，满6后下一轮炮击；敌人清空后每轮充能+2。',
 'N09-2':'击败敌方。',
 'N10-1':'6轮内击败敌人并完成2次身份核验。博士技艺或伊内丝A可核验；倒地目标在下一轮自动核验。',
 'N11-4':'击败君主；或每累计2次博士防御发射1枚装药，命中3次并坚持至第8轮。',
 'N12-1':'击败敌方；或每累计2次博士防御引流1次，成功3次并坚持至第6轮。',
 'N12-4':'破坏2个茧笼；或博士休整/防御且队友攻击的轮次累计6次，并坚持至第8轮。'
};
export function mission(spec){return ((spec.solo&&spec.goal)||missions[spec.id]||spec.goal||'击败敌方').replace(/HP/g,'生命').replace(/H(\d+)/g,'生命$1').replace(/D(\d+)/g,'防御$1').replace(/R(\d+)/g,'魔抗$1').replace(/玩家/g,'博士').replace(/场景轮/g,'轮');}
